import XCTest
@testable import AuthCore

final class BookingServicesTests: XCTestCase {
    private struct Expected: Decodable {
        var names: [String: String]
        var labels: [String: [String: String?]]
        var offered: [String: [String]]
    }

    /// The website's own answers, generated by `src/security/iosBookingServices.test.ts`.
    private func load() throws -> Expected {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("service-prices.json")
        return try JSONDecoder().decode(Expected.self, from: Data(contentsOf: url))
    }

    func testEveryServiceAndSizeGetsTheWebsitesPriceLabel() throws {
        let expected = try load()
        var checked = 0
        for service in BookingService.allCases {
            XCTAssertEqual(expected.names[service.webId], service.rawValue, "the website's name for \(service.webId)")
            for size in [DogSize.small, .medium, .large] {
                let website = try XCTUnwrap(expected.labels[service.webId]?[size.rawValue], "\(service.webId) \(size)")
                XCTAssertEqual(service.priceLabel(for: size), website, "\(service.webId) / \(size)")
                checked += 1
            }
        }
        XCTAssertEqual(checked, 12)
    }

    func testTheServicesOfferedForEachSizeAreTheWebsitesInTheSalonsOrder() throws {
        let expected = try load()
        for size in [DogSize.small, .medium, .large] {
            XCTAssertEqual(BookingService.offered(for: size).map(\.webId), expected.offered[size.rawValue], "\(size)")
        }
    }

    /// Two rules in Swift must say the same thing: the service is offered exactly when it has a price.
    func testOfferedAndPricedAreTheSameThing() {
        for service in BookingService.allCases {
            for size in [DogSize.small, .medium, .large] {
                XCTAssertEqual(
                    service.isOffered(forSize: size.rawValue),
                    service.pricePence(for: size) != nil,
                    "\(service) / \(size)"
                )
            }
        }
    }

    func testThePriceLinesReadTheWayTheWebsiteRendersThem() {
        XCTAssertEqual(BookingService.fullGroom.priceLine(for: .medium), "From £46+")
        XCTAssertEqual(BookingService.puppyGroom.priceLine(for: .small), "From £38")
        XCTAssertNil(BookingService.puppyGroom.priceLine(for: .large), "not offered for a large dog")
    }

    func testPoundsAreFormattedLikeTheWebsite() {
        XCTAssertEqual(BookingService.formatPounds(4200), "£42")
        XCTAssertEqual(BookingService.formatPounds(1000), "£10")
        XCTAssertEqual(BookingService.formatPounds(4250), "£42.50")
        XCTAssertEqual(BookingService.formatPounds(4205), "£42.05")
        XCTAssertEqual(BookingService.formatPounds(0), "£0")
    }

    func testEachServiceHasADescriptionAndAMascot() {
        for service in BookingService.allCases {
            XCTAssertFalse(service.summary.isEmpty, service.rawValue)
            XCTAssertNotNil(ServiceMascot.assetName(forService: service.rawValue), service.rawValue)
        }
        XCTAssertTrue(BookingService.startingPriceNote.contains("starting prices"))
    }
}
